target = open("/tmp/target_380.txt").read().strip()
n = len(target)
stack = []
pairs = {}
for i,c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pairs[j] = i
        pairs[i] = j

# Build with: all pairs GC alternating, loops alternate A/U to avoid structure
seq = ['A']*n
pairlist = sorted([(i,pairs[i]) for i in pairs if i < pairs[i]])
for idx,(i,j) in enumerate(pairlist):
    if idx % 2 == 0:
        seq[i]='G'; seq[j]='C'
    else:
        seq[i]='C'; seq[j]='G'
# Now set unpaired positions to alternating U/A to break up runs
unpaired = [i for i in range(n) if i not in pairs]
for k,i in enumerate(unpaired):
    seq[i] = 'U' if k % 2 == 0 else 'A'
print(''.join(seq))
